// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.concurrent.atomic.AtomicBoolean;

import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Gap-analysis B7: the adjacency subject prefix-run cursor's {@code seekTo} past the last key must exhaust the cursor.
 * The historical implementation returned {@code false} without repositioning or closing the underlying root cursor, and
 * {@code next()} is cursor-driven — so a composite merge that probes {@code seekTo} beyond one member's last key and
 * later calls {@code next()} again (which {@code CompositeNativeLmdbQuerySource}'s merge does whenever another member
 * refills the head array) re-emitted subjects <em>below</em> the seek target: duplicate groups, a broken
 * nondecreasing-head invariant, and double-counted {@code runRowCount}. Keys are sorted, so past-end means exhausted
 * forever; the sibling predicate cursor is ordinal-driven and immune.
 */
class LmdbDirectAdjacencyPrefixRunSeekTest {

	private TripleStore tripleStore;
	private LmdbDirectAdjacencyStore store;

	private static long uri(long payload) {
		return ValueIds.createId(ValueIds.T_URI, payload);
	}

	private static final long P1 = uri(100);
	private static final long O1 = uri(11);

	@TempDir
	File dataDir;

	@AfterEach
	void tearDown() throws Exception {
		if (store != null) {
			store.close();
		}
		if (tripleStore != null) {
			tripleStore.close();
		}
	}

	private void open() throws Exception {
		tripleStore = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbDirectAdjacencyOptions options = LmdbDirectAdjacencyOptions.resolve(config, 8L << 30, name -> null, 4);
		store = new LmdbDirectAdjacencyStore(tripleStore, null, new AtomicBoolean(false), options);
		tripleStore.setDirectAdjacencyCommitHooks(store.commitListener(), store.newCommitDelta());

		tripleStore.startTransaction();
		for (long subject = 1; subject <= 5; subject++) {
			tripleStore.storeTriple(uri(subject), P1, O1, 0, true);
		}
		tripleStore.commit();
		store.applyCommitted(tripleStore.drainDirectAdjacencyCommitDelta());
		assertThat(store.buildNowForTest()).isTrue();
	}

	@Test
	void seekPastTheLastKeyExhaustsTheCursor() throws Exception {
		open();
		LmdbPrefixRunPlan plan = LmdbPrefixRunPlan.adjacencySubject(new int[] { TripleIndex.SUBJ_IDX });
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			LmdbPrefixRunCursor cursor = store.tryPrefixRuns(view, plan, -1, P1, -1, -1, true, false);
			assertThat(cursor).as("adjacency-served subject prefix-run cursor").isNotNull();
			try {
				assertThat(cursor.next()).as("first prefix").isTrue();
				assertThat(cursor.quad()[TripleIndex.SUBJ_IDX]).isEqualTo(uri(1));

				assertThat(cursor.seekTo(uri(999))).as("no key at or beyond the seek target").isFalse();
				assertThat(cursor.next())
						.as("a past-end seek exhausts the cursor: next() must not re-emit subjects below the "
								+ "seek target from the stale root-cursor position")
						.isFalse();
			} finally {
				cursor.close();
			}
		}
	}

	/** An in-range seek still repositions and serves the remaining keys — the fix must not over-close. */
	@Test
	void seekWithinRangeStillServesRemainingKeys() throws Exception {
		open();
		LmdbPrefixRunPlan plan = LmdbPrefixRunPlan.adjacencySubject(new int[] { TripleIndex.SUBJ_IDX });
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			LmdbPrefixRunCursor cursor = store.tryPrefixRuns(view, plan, -1, P1, -1, -1, true, false);
			assertThat(cursor).isNotNull();
			try {
				assertThat(cursor.next()).isTrue();
				assertThat(cursor.seekTo(uri(4))).as("keys at or beyond the target remain").isTrue();
				assertThat(cursor.next()).isTrue();
				assertThat(cursor.quad()[TripleIndex.SUBJ_IDX]).isEqualTo(uri(4));
				assertThat(cursor.next()).isTrue();
				assertThat(cursor.quad()[TripleIndex.SUBJ_IDX]).isEqualTo(uri(5));
				assertThat(cursor.next()).isFalse();
			} finally {
				cursor.close();
			}
		}
	}
}
